type:
∀ (j : ℕ),
  Shao.OQ5.P35.categorySupportBlock j =
    {x | Shao.OQ5.P35.decodeCategory x = j ∧ Shao.OQ5.P35.decodeNoise x ∈ Set.Icc (-1) 1}

∀ (ν : MeasureTheory.Measure ℝ) [MeasureTheory.IsProbabilityMeasure ν] (n j : ℕ) (x : ℝ),
  2 ≤ x →
    x ^ 6 ≤ ↑n →
      ↑j ≤ x ^ 2 / 2 →
        MeasureTheory.Integrable (fun z => z ^ 2) ν →
          ∫ (z : ℝ), z ∂ν = 0 →
            ↑n * ∫ (z : ℝ), z ^ 2 ∂ν = 1 →
              ↑n * ∫ (z : ℝ), Shao.truncationF (x * z) ∂ν ≤ 1 →
                have μx := ∫ (z : ℝ), z ∂Shao.retainedCutoffLaw ν x;
                have Vx := ∫ (z : ℝ), (z - μx) ^ 2 ∂Shao.retainedCutoffLaw ν x;
                have M := ↑(n - j);
                have y := √(x ^ 2 - ↑j);
                (∫ (z : ℝ), |z - μx| ^ 3 ∂Shao.retainedCutoffLaw ν x) / (√M * √Vx ^ 3) ≤ 64 / y ^ 3

∀ {n : ℕ} {Ω : Type u_1} [inst : MeasurableSpace Ω] {X : Fin n → Ω → ℝ},
  (∀ (i : Fin n), Measurable (X i)) →
    ∀ (B : Set ℝ), MeasurableSet B → ∀ (s : Finset (Fin n)), MeasurableSet {ω | Shao.Probability.retentionSet X B ω = s}

∀ {n : ℕ} {Ω : Type u_1} [inst : MeasurableSpace Ω] {μ : MeasureTheory.Measure Ω} {ν : MeasureTheory.Measure ℝ}
  [MeasureTheory.IsProbabilityMeasure μ] [MeasureTheory.IsProbabilityMeasure ν] {X : Fin n → Ω → ℝ},
  (∀ (i : Fin n), Measurable (X i)) →
    ProbabilityTheory.iIndepFun X μ →
      (∀ (i : Fin n), ProbabilityTheory.IdentDistrib (X i) id μ ν) →
        ∀ (s : Finset (Fin n)) (x : ℝ),
          2 ≤ x →
            x ^ 6 ≤ ↑n →
              ↑(n - s.card) ≤ x ^ 2 / 2 →
                MeasureTheory.Integrable (fun z => z ^ 2) ν →
                  ∫ (z : ℝ), z ∂ν = 0 →
                    ↑n * ∫ (z : ℝ), z ^ 2 ∂ν = 1 →
                      ↑n * ∫ (z : ℝ), Shao.truncationF (x * z) ∂ν ≤ 1 →
                        μ {ω | Shao.Probability.retentionSet X (Shao.retainedCutoffSet x) ω = s} ≠ 0 →
                          have A := {ω | Shao.Probability.retentionSet X (Shao.retainedCutoffSet x) ω = s};
                          have j := n - s.card;
                          have η := Shao.retainedCutoffLaw ν x;
                          have ζ := Shao.retainedStandardLaw ν x;
                          have μx := ∫ (z : ℝ), z ∂η;
                          have τx := √(∫ (z : ℝ), (z - μx) ^ 2 ∂η);
                          have y := √(x ^ 2 - ↑j);
                          ∃ (hn : 0 < n) (hs : 0 < s.card),
                            μ[{ω | Shao.Probability.samplePath X ω ∈ Shao.upperCrossing hn x} | A] ≤
                                (MeasureTheory.Measure.pi fun x => η) (Shao.upperCrossing hs y) ∧
                              (MeasureTheory.Measure.pi fun x => η) (Shao.upperCrossing hs y) =
                                (MeasureTheory.Measure.pi fun x => ζ)
                                  {a | (fun r => μx + τx * a r) ∈ Shao.upperCrossing hs y}

∀ (ν : MeasureTheory.Measure ℝ) [MeasureTheory.IsProbabilityMeasure ν],
  MeasureTheory.Integrable (fun a => |a| ^ 3) ν →
    ∀ (u v : ℝ),
      have μ := ∫ (a : ℝ), a ∂ν;
      have m3 := ∫ (a : ℝ), |a| ^ 3 ∂ν;
      have d := fun r => Shao.Probability.quadraticChar ν r v - Shao.Probability.quadraticChar ν (-r) v;
      ‖deriv d u - 2 * Complex.I * ↑μ‖ ≤ m3 * (u ^ 2 + 2 * |v|) ∧ ‖deriv (fun r => deriv d r) u‖ ≤ 2 * m3 * |u|
